package nx.updater;
import java.nio.file.*;import java.nio.channels.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.function.*;
/** Shipped helper. No downloaded executable is started by this installer. */
public final class UpdateInstaller {
 public interface Fault {void afterWrite(int index)throws Exception;}
 private final UpdateConfig config;
 public UpdateInstaller(UpdateConfig c){config=c;}
 public static void noLinks(Path root,Path p)throws Exception{Path r=root.toAbsolutePath().normalize();p=p.toAbsolutePath().normalize();if(!p.startsWith(r))throw new SecurityException("Directorio exterior");for(Path x=p;x!=null&&x.startsWith(r);x=x.getParent())if(Files.isSymbolicLink(x))throw new SecurityException("Enlace simbólico rechazado");}
 public static void atomic(Path path,byte[] data)throws Exception{Files.createDirectories(path.getParent());Path t=Files.createTempFile(path.getParent(),"nx-",".tmp");try{try(FileChannel out=FileChannel.open(t,StandardOpenOption.WRITE)){java.nio.ByteBuffer b=java.nio.ByteBuffer.wrap(data);while(b.hasRemaining())out.write(b);out.force(true);}try{Files.move(t,path,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(t,path,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(t);}}
 public static void atomicCopy(Path source,Path dest)throws Exception{Files.createDirectories(dest.getParent());Path tmp=Files.createTempFile(dest.getParent(),"nx-",".tmp");try{try(FileChannel in=FileChannel.open(source,StandardOpenOption.READ);FileChannel out=FileChannel.open(tmp,StandardOpenOption.WRITE)){java.nio.ByteBuffer b=java.nio.ByteBuffer.allocate(65536);while(in.read(b)>=0){b.flip();while(b.hasRemaining())out.write(b);b.clear();}out.force(true);}try{Files.move(tmp,dest,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException ex){Files.move(tmp,dest,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(tmp);}}
 private void journal(Properties p)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();p.store(b,"NX Updater transaction");atomic(config.work.resolve("transaction.properties"),b.toByteArray());}
 private Properties journal()throws Exception{Properties p=new Properties();Path f=config.work.resolve("transaction.properties");if(Files.exists(f))try(InputStream in=Files.newInputStream(f)){p.load(in);}return p;}
 public Path prepare(GitHubReleases.Offer offer,DownloadManager http,BooleanSupplier cancel,DownloadManager.Progress progress)throws Exception{noLinks(config.root,config.work);Path stage=config.work.resolve("staged").resolve(offer.manifest.version);noLinks(config.root,stage);Files.createDirectories(stage);atomic(stage.resolve("manifest.json"),offer.raw);atomic(stage.resolve("manifest.sig"),offer.signature);long complete=0;for(UpdateManifest.Entry e:offer.manifest.files){if(e.action.equals("DELETE"))continue;if(cancel.getAsBoolean())throw new InterruptedIOException("Cancelado");final long prior=complete;http.download(e,stage.resolve("downloads"),cancel,(done,total,speed,status)->progress.update(prior+done,offer.manifest.totalBytes,speed,status));complete+=e.size;}return stage;}
 private UpdateManifest manifest(Path stage)throws Exception{noLinks(config.root,stage);if(!stage.normalize().startsWith(config.work.resolve("staged")))throw new SecurityException("Área de preparación inválida");return UpdateManifest.verified(Files.readAllBytes(stage.resolve("manifest.json")),Files.readAllBytes(stage.resolve("manifest.sig")),UpdateManifest.publicKey(config.trustedKey));}
 public void install(Path stage,Fault fault)throws Exception{noLinks(config.root,config.work);Files.createDirectories(config.work);try(FileChannel ch=FileChannel.open(config.work.resolve("install.lock"),StandardOpenOption.CREATE,StandardOpenOption.WRITE);FileLock lock=ch.tryLock()){if(lock==null)throw new IOException("Otra instalación está activa");recover();UpdateManifest m=manifest(stage);m.compatible(new UpdateConfig(config.root).installed,config.platform,config.channel,config.protocol);
   Path backup=stage.resolve("backup");noLinks(config.root,backup);Files.createDirectories(backup);
   // Validate the WHOLE plan before touching any installed file.
   for(int i=0;i<m.files.size();i++){UpdateManifest.Entry e=m.files.get(i);Path dst=UpdateManifest.target(config.root,e.path);if(e.action.equals("ADD")){if(Files.exists(dst))throw new IOException("Archivo ADD ya existe: "+e.path);}else if(!Files.isRegularFile(dst)||!DownloadManager.sha(dst).equals(e.oldSha256))throw new IOException("Base modificada; se conserva: "+e.path);if(!e.action.equals("DELETE")){Path bin=stage.resolve("downloads").resolve(e.sha256+".bin");noLinks(config.root,bin);if(!Files.isRegularFile(bin)||Files.size(bin)!=e.size||!DownloadManager.sha(bin).equals(e.sha256))throw new SecurityException("Preparación corrupta: "+e.path);}
    if(!e.action.equals("ADD")){Path back=backup.resolve(i+".bin");Files.copy(dst,back,StandardCopyOption.REPLACE_EXISTING);if(!DownloadManager.sha(back).equals(e.oldSha256))throw new IOException("Respaldo inválido");}}
   Path meta=config.work.resolve("installed.properties");if(Files.exists(meta))Files.copy(meta,stage.resolve("previous-installed.properties"),StandardCopyOption.REPLACE_EXISTING);else Files.deleteIfExists(stage.resolve("previous-installed.properties"));
   Properties j=new Properties();j.setProperty("stage",config.work.relativize(stage).toString());j.setProperty("status","INSTALLING");journal(j);
   try{for(int i=0;i<m.files.size();i++){UpdateManifest.Entry e=m.files.get(i);Path dst=UpdateManifest.target(config.root,e.path);j.setProperty("pendingIndex",Integer.toString(i));journal(j);if(e.action.equals("DELETE"))Files.delete(dst);else atomicCopy(stage.resolve("downloads").resolve(e.sha256+".bin"),dst);if(fault!=null)fault.afterWrite(i);}
    for(UpdateManifest.Entry e:m.files){Path p=UpdateManifest.target(config.root,e.path);if(e.action.equals("DELETE")?Files.exists(p):!DownloadManager.sha(p).equals(e.sha256))throw new IOException("Verificación final falló");}atomic(meta,("version="+m.version+"\nplatform="+m.platform+"\nprotocol="+m.protocol+"\n").getBytes(StandardCharsets.UTF_8));j.setProperty("status","COMMITTED");journal(j);
   }catch(Exception ex){rollback(stage,m);j.setProperty("status","ROLLED_BACK");journal(j);throw ex;}
  }}
 private void rollback(Path stage,UpdateManifest m)throws Exception{Path backup=stage.resolve("backup");for(int i=0;i<m.files.size();i++){UpdateManifest.Entry e=m.files.get(i);Path p=UpdateManifest.target(config.root,e.path);if(e.action.equals("ADD")){if(Files.exists(p)){if(!DownloadManager.sha(p).equals(e.sha256))throw new IOException("Cambio externo al restaurar ADD; conservado");Files.delete(p);}}else{Path b=backup.resolve(i+".bin");noLinks(config.root,b);if(!Files.isRegularFile(b)||!DownloadManager.sha(b).equals(e.oldSha256))throw new IOException("Respaldo inválido al restaurar");if(Files.exists(p)&&!DownloadManager.sha(p).equals(e.oldSha256)&&!DownloadManager.sha(p).equals(e.sha256==null?e.oldSha256:e.sha256)){Path conflict=stage.resolve("conflict-"+i+".bin");Files.copy(p,conflict,StandardCopyOption.REPLACE_EXISTING);}atomicCopy(b,p);}}
  Path previous=stage.resolve("previous-installed.properties");if(Files.exists(previous))atomic(config.work.resolve("installed.properties"),Files.readAllBytes(previous));else Files.deleteIfExists(config.work.resolve("installed.properties"));}
 public boolean recover()throws Exception{noLinks(config.root,config.work);Properties j=journal();if(!j.getProperty("status","").equals("INSTALLING"))return false;Path stage=config.work.resolve(j.getProperty("stage")).normalize();UpdateManifest m=manifest(stage);rollback(stage,m);j.setProperty("status","ROLLED_BACK");journal(j);return true;}
 public void restorePrevious()throws Exception{Properties j=journal();if(!j.getProperty("status","").equals("COMMITTED"))throw new IOException("No hay versión anterior disponible");Path stage=config.work.resolve(j.getProperty("stage")).normalize();rollback(stage,manifest(stage));j.setProperty("status","ROLLED_BACK");journal(j);}
 public static void main(String[] args)throws Exception{if(args.length!=3)throw new IllegalArgumentException("root stage install|restore");UpdateConfig c=new UpdateConfig(Paths.get(args[0]));Files.createDirectories(c.work);noLinks(c.root,c.work);try(FileChannel ch=FileChannel.open(c.work.resolve("game.lock"),StandardOpenOption.CREATE,StandardOpenOption.WRITE)){FileLock lease=null;for(int t=0;t<120&&lease==null;t++){try{lease=ch.tryLock();}catch(OverlappingFileLockException ex){}if(lease==null)Thread.sleep(500);}if(lease==null)throw new IOException("El juego sigue abierto; instalación aplazada");try{UpdateInstaller i=new UpdateInstaller(new UpdateConfig(c.root));if(args[2].equals("restore"))i.restorePrevious();else if(args[2].equals("install"))i.install(Paths.get(args[1]),null);else throw new IOException("Acción desconocida");}finally{lease.release();}}}
}
